widget.solution:
#include <string>

class Money {
public:
    explicit Money(long long pence) : pence_(pence) {}
    long long pence() const { return pence_; }

    std::string str() const {
        long long p = pence_ < 0 ? -pence_ : pence_;
        std::string cents = std::to_string(p % 100);
        if (cents.size() < 2) cents = "0" + cents;
        std::string sign = pence_ < 0 ? "-" : "";
        return sign + "£" + std::to_string(p / 100) + "." + cents;
    }

private:
    long long pence_;
};

Money operator+(Money a, Money b) { return Money(a.pence() + b.pence()); }
Money operator*(Money m, int k) { return Money(m.pence() * k); }

screens.prose:
Python prints an object through `__repr__`. C++ prints through `operator<<`, which takes the stream by reference and returns it.

```cpp
std::ostream& operator<<(std::ostream& os,
                         const Money& m) {
    os << m.str();
    return os;
}

std::cout << Money(1250) << " + " << Money(399) << '\n';
```

explain.text:
`Money& a` is `cash` itself, so the sum is written into it. A reader of `cash + fee` never expects `cash` to change. Keep `+` pure and put mutation in `+=`:

```cpp
Money operator+(Money a, Money b) {        // new value
    return Money{a.pence + b.pence};
}
Money& operator+=(Money& a, Money b) {     // says it writes
    a.pence += b.pence;
    return a;
}
```

