std::vector<long long> sorted_pence(std::vector<long long> ps) {
    std::vector<Price> v;
    for (long long p : ps) v.push_back(Price{p, "LSE"});
    std::sort(v.begin(), v.end());
    std::vector<long long> out;
    for (const Price& p : v) out.push_back(p.pence);
    return out;
}

long long lowest(std::vector<long long> ps) { return sorted_pence(ps).front(); }

